/// <summary>
/// Gets the primary telephone number extension for the selected address book record.
/// </summary>
/// <returns>
/// The primary telephone number extension for the address book record.
/// </returns>
//BP deviation documented
[SysClientCacheDataMethodAttribute(true)]
public PhoneLocal avaPrimaryPhoneExtension()
{
    LogisticsElectronicAddress electronicAddress;
    select firstonly Locator from electronicAddress where electronicAddress.RecId == this.PrimaryContactPhone;
    return electronicAddress.LocatorExtension;
}

/// <summary>
///    AVA <c>AVAgetLogisticsElectronicAddress</c> method.
/// </summary>
/// <param name="_logisticsElectronicAddressMethodType">
///    <c>LogisticsElectronicAddressMethodType</c> as type
/// </param>
/// <param name="_isPrivate">
///    <c>boolean</c> as type
/// </param>
/// <param name="_isPrimary">
///    <c>boolean</c> as type
/// </param>
/// <param name="_isMobilePhone">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>LogisticsElectronicAddress</c> as return value
/// </returns>
public LogisticsElectronicAddress AVAgetLogisticsElectronicAddress( LogisticsElectronicAddressMethodType    _logisticsElectronicAddressMethodType   = LogisticsElectronicAddressMethodType::Phone,
                                                                    boolean                                 _isPrivate                              = false,
                                                                    boolean                                 _isPrimary                              = true,
                                                                    boolean                                 _isMobilePhone                          = false
                                                                    )
{
    LogisticsElectronicAddress  locLogisticsElectronicAddress;
    DirPartyLocation            locDirPartyLocation;

    select firstOnly *
    from    locLogisticsElectronicAddress
    where   locLogisticsElectronicAddress.Type              == _logisticsElectronicAddressMethodType
        &&  locLogisticsElectronicAddress.IsPrivate         == _isPrivate
        &&  locLogisticsElectronicAddress.IsPrimary         == _isPrimary
        &&  locLogisticsElectronicAddress.IsMobilePhone     == _isMobilePhone
        exists join locDirPartyLocation
        where   locDirPartyLocation.Location          == locLogisticsElectronicAddress.Location
            && locDirPartyLocation.Party              == this.RecId
            && locDirPartyLocation.IsPostalAddress    == NoYes::No;

    return locLogisticsElectronicAddress;
}

/// <summary>
///    AVA <c>AVAgetAvailableLogisticsElectronicAddressLocator</c> method.
/// </summary>
/// <param name="_logisticsElectronicAddressMethodType">
///    <c>LogisticsElectronicAddressMethodType</c> as type
/// </param>
/// <param name="_isMobilePhone">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>LogisticsElectronicAddressLocator</c> as return value
/// </returns>
public LogisticsElectronicAddressLocator AVAgetAvailableLogisticsElectronicAddressLocator(  LogisticsElectronicAddressMethodType    _logisticsElectronicAddressMethodType   = LogisticsElectronicAddressMethodType::Phone,
                                                                                            boolean                                 _isMobilePhone                          = false
                                                                                            )
{
    LogisticsElectronicAddressLocator   retVal;
    boolean                             isMobilePhone;

    isMobilePhone = _isMobilePhone;
    if(_logisticsElectronicAddressMethodType != LogisticsElectronicAddressMethodType::Phone)
    {
        isMobilePhone = false;
    }

    retVal = this.AVAgetLogisticsElectronicAddress( _logisticsElectronicAddressMethodType,
                                                    false,
                                                    true,
                                                    isMobilePhone
                                                    ).Locator;
    if (!retVal)
    {
        retVal = this.AVAgetLogisticsElectronicAddress( _logisticsElectronicAddressMethodType,
                                                        false,
                                                        false,
                                                        isMobilePhone
                                                        ).Locator;
    }

    return retVal;
}

